assert len(CIT_HE) == 26 and len(CIT_EN) == 122, (len(CIT_HE), len(CIT_EN))
assert [(p, r, v) for p, r, v in CIT_HE if p not in PISKAOT] == OUTSIDE_HE
SPINE_CITES_HE = [(p, r, v) for p, r, v in CIT_HE if p in PISKAOT]
assert len(SPINE_CITES_HE) == 22 and SPINE_CITES_HE[:6] == [(82, 1, (13, 1)), (83, 1, (13, 2)), (84, 1, (13, 3)), (84, 3, (13, 4)), (85, 1, (13, 5)), (86, 1, (13, 6))] and SPINE_CITES_HE.count((87, 13, (13, 8))) == 2 and (86, 6, (13, 11)) in SPINE_CITES_HE and (93, 6, (13, 15)) in SPINE_CITES_HE and SPINE_CITES_HE[-3:] == [(96, 1, (13, 17)), (96, 2, (13, 18)), (96, 6, (13, 19))]
